import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Create Your SaaS Project","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/create-project","contentType":"guide","prev":{"text":"Developer documentation","link":"/en/docs/"},"next":{"text":"Quick start","link":"/en/getting-started/quickstart"}},"headers":[],"relativePath":"en/getting-started/create-project.md","filePath":"en/getting-started/create-project.md"}'),n={name:"en/getting-started/create-project.md"};function r(o,e,p,c,l,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="create-your-saas-project" tabindex="-1">Create Your SaaS Project <a class="header-anchor" href="#create-your-saas-project" aria-label="Permalink to &quot;Create Your SaaS Project&quot;">​</a></h1><p>Use the Dougong creator to generate a renamed project, choose whether to retain reference applications, and allocate isolated local development ports.</p><h2 id="_1-create-a-copy" tabindex="-1">1. Create a Copy <a class="header-anchor" href="#_1-create-a-copy" aria-label="Permalink to &quot;1. Create a Copy&quot;">​</a></h2><p>Prepare Node 24.18.0. Running the application also requires Rust 1.96.0, pnpm 11.17.0, just 1.58.0 and Docker Compose.</p><p>Create a project from npm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-axum-saas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>Omit the directory to be prompted for a project name. The final directory name must use lowercase kebab-case, start with a letter, and contain at most 48 characters. Existing directories are rejected without overwriting files. Knowledge, Notes and the teaching fixtures are included by default.</p><p>You can also build the current source snapshot and use a local package from the template repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scaffold:pack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.scratch/create-package/create-axum-saas-0.1.2.tgz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-axum-saas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>The package contains its source snapshot. Creation does not fetch a changing Git branch or install dependencies. The result excludes <code>.git</code>, local secrets, data volumes and build directories.</p><h2 id="_2-run-and-verify" tabindex="-1">2. Run and Verify <a class="header-anchor" href="#_2-run-and-verify" aria-label="Permalink to &quot;2. Run and Verify&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The creator writes available ports to <code>.env</code>. Development scripts derive connection URLs, bindings, proxy targets and browser origins from those ports. Startup prints this copy&#39;s Web, API, Worker and Mailpit URLs. Open <code>/register</code> on the Web origin, create an account, sign out, then sign in at <code>/login</code>. The first account is Owner; passwords require 12–128 characters.</p><p>Keep development running. In another terminal at the project root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project_api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-type=module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;import { developmentEnv } from &quot;./scripts/lib/process.mjs&quot;; console.log(developmentEnv().APP_BIND)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$project_api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/ready&quot;</span></span></code></pre></div><p>Expect HTTP 200 with <code>x-request-id</code>. <code>Ctrl+C</code> stops host processes; <code>just services-down</code> stops dependencies and preserves volumes.</p><h2 id="_3-keep-only-core" tabindex="-1">3. Keep Only Core <a class="header-anchor" href="#_3-keep-only-core" aria-label="Permalink to &quot;3. Keep Only Core&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-axum-saas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plain-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-examples</span></span></code></pre></div><p><code>--no-examples</code> removes all reference businesses and the ticket teaching fixture, example tools, compilation references, dedicated migrations, tests and CI jobs. Contracts and lockfiles are regenerated when the package is built. Identity, membership, authorization, audit, Jobs, files, notifications and other shared capabilities remain. Registration and login land on the generic home. Documentation retains a minimal bilingual development entry and Core API/configuration references.</p><p>The project name applies to npm scopes, Rust crates, SQL schemas, metrics, cookies, browser storage keys, the Electron bridge and local credentials. Set your repository with <code>--repository owner/repo</code>; otherwise links use <code>your-org/&lt;project-name&gt;</code> until you configure the actual repository. License attribution is preserved.</p><h2 id="_4-multiple-copies-and-recovery" tabindex="-1">4. Multiple Copies and Recovery <a class="header-anchor" href="#_4-multiple-copies-and-recovery" aria-label="Permalink to &quot;4. Multiple Copies and Recovery&quot;">​</a></h2><p>Create two directories, install each, and run their <code>just dev</code> commands. Reservations live in <code>create-axum-saas/ports.json</code> under the user cache directory, so copies that have not started yet still get distinct ports. The registry contains only paths and ports; records for deleted directories are removed on the next creation.</p><p>The development entry derives a Compose namespace from the directory name and full path. Identically named directories under different parents also get independent containers, volumes and networks. Previous development volumes remain and are not adopted automatically. To deliberately reuse a previous namespace, set <code>COMPOSE_PROJECT_NAME</code> in the process environment and retain its ports and credentials.</p><p>A port can become occupied after creation, so startup checks again every time. Conflicts identify a host listener/PID or Docker container/project and suggest stopping the owner or changing the corresponding <code>*_PORT</code> in <code>.env</code>. Healthy containers without actual bindings fail before migrations. Migration errors preserve the real SQLx cause.</p><p>Do not delete volumes to resolve a port conflict. Continue with <a href="./../architecture/project-structure">project structure</a> and <a href="./../guides/new-module">adding a business module</a>. A generated Core copy can begin its own business under <code>crates/app/src/modules</code>.</p><h2 id="_5-publish-the-cli-as-a-template-maintainer" tabindex="-1">5. Publish the CLI as a Template Maintainer <a class="header-anchor" href="#_5-publish-the-cli-as-a-template-maintainer" aria-label="Permalink to &quot;5. Publish the CLI as a Template Maintainer&quot;">​</a></h2><p>Update the version in <code>tools/create-axum-saas/package.json</code> and merge it into <code>main</code> through a PR; published npm versions cannot be overwritten. Wait for CI on that main commit to pass.</p><p>The repository Actions Secret <code>NPM_TOKEN</code> must hold a granular token limited to <code>create-axum-saas</code>, with <code>Read and write (publish and stage)</code> permission and <code>Bypass two-factor authentication</code> enabled. Replace the Secret when it expires; Actions publishing requires no interactive login.</p><p>Open <a href="https://github.com/CaiZongyuan/axum-saas-template/actions/workflows/npm-publish.yml" target="_blank" rel="noreferrer">Publish creator</a>, choose <code>Run workflow</code> on <code>main</code>, and enter the package metadata&#39;s <code>version</code>. Leave <code>publish</code> unchecked for a dry run and inspect the npm identity, package contents and successful result. Then dispatch the same version with <code>publish</code> checked. Publishing checks that the version is unregistered, builds reference and Core snapshots, and waits for registry integrity to match the archive. On failure, check the version, token permissions and expiration; do not republish a version that already succeeded.</p><p><a href="https://docs.npmjs.com/about-access-tokens/" target="_blank" rel="noreferrer">npm&#39;s token policy</a>plans to remove direct new-version publishing with tokens in January 2027; migrate to Trusted Publishing or the new staging flow then. This maintainer workflow, release script and tests are excluded from generated projects.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/getting-started/create-project.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,32)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
